import assert from 'node:assert/strict';
import {Miniflare,convertV4MiniflareOptions} from 'miniflare';

// Uses the bundle generated by check:worker. No credentials, deployment, or remote GitHub calls.
const runtime=new Miniflare(convertV4MiniflareOptions({modules:true,scriptPath:'.worker-build/index.js',compatibilityDate:'2026-10-13',durableObjects:{SECURITY:{className:'ProbeSecurity',useSQLite:true}},bindings:{ALLOWED_ORIGIN:'https://pgt.example',DATA_BRANCH:'main'}}));
try{
  const unauthorized=await runtime.dispatchFetch('http://localhost/api/probe/users/a@example.com/json');
  const unknown=await runtime.dispatchFetch('http://localhost/api/unknown');
  assert.equal(unauthorized.status,401);assert.equal(unknown.status,404);
  assert.deepEqual(await unauthorized.json(),{error:'PGT_SESSION_REQUIRED'});
  console.log('Runtime Worker/SQLite DO local: sesión ausente 401; endpoint inexistente 404.');
}finally{await runtime.dispose();}
